<?php require_once __DIR__.'/../config/config.php';role_required(['admin']);$pageTitle='All Manuscripts';$rows=db()->query("SELECT m.*,u.full_name author FROM manuscripts m LEFT JOIN users u ON u.id=m.corresponding_author_id ORDER BY m.updated_at DESC")->fetchAll();include __DIR__.'/../includes/header.php';?><h1 class="title">All Manuscripts</h1><div class="panel"><table><tr><th>ID</th><th>Title</th><th>Author</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['manuscript_no'])?></td><td><?=e($r['title'])?></td><td><?=e($r['author'])?></td><td><?=e(slabel($r['status']))?></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/../includes/footer.php';?>